{SELECT Paper_Authors.rank , Paper.n_citation FROM Author JOIN Paper_Authors ON Author.id = Paper_Authors.author_id JOIN Paper ON Paper_Authors.paper_id = Paper.id WHERE Paper_Authors.rank < 3}
